Given a condition $\mathbf{c}$, consider the conditional densities $\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ and $\tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ induced by (25) and (26), respectively. We have the following results.
\begin{enumerate}
    \item[(a)] If $\tilde{\mathbf{Y}}(\tau_k)$ follows the marginal density $\tilde p_{\tau_k}$ of the reverse SDE (4), then
    \begin{align*}
        \mathbb{E}_{\tilde{\mathbf{Y}}(\tau_k)\sim\tilde p_{\tau_k}} \bigg[\lim_{\tau \to \tau_k+}\text{KL}\big(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k)) || \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{Y}}(\tau_k))\big)\bigg] = 0.
    \end{align*}

    \item[(b)] For any given initial $\tilde{\mathbf{z}}$ and $\tau\in(\tau_k, \tau_{k + 1}]$,
    \begin{align}
        &\frac{\mathrm{d}}{\mathrm{d} \tau}\text{KL}\big(\tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}}) || \tilde p^\theta_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})\big) \\
        & \le \frac{1}{C_{KL}}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\big\|\tilde f(\tau)\tilde{\mathbf{Y}}(\tau) - \tilde f(\tau_k)\tilde{\mathbf{z}} + \tilde g^2(\tau)\nabla\log q_{T_g - \tau}(\tilde{\mathbf{Y}}(\tau)|\mathbf{c}) -  \tilde g^2(\tau_k)s_\theta(T_g - \tau_k, \tilde{\mathbf{z}}, \mathbf{c})\big\|^2 \\
        & \qquad +\frac{[\tilde g^2(\tau_k) - \tilde g^2(\tau)]^2}{4C_{KL}}\mathbb{E}_{\tilde{\mathbf{Y}}(\tau)} \big[\big\|\nabla\log\tilde p_\tau(\tilde{\mathbf{Y}}(\tau))\big\|^2\big] \\
        &\qquad + \frac{1}{2}\bigg[C_{KL} - \tilde g^2(\tau_k)\bigg] \mathbb{E}_{\tilde{\mathbf{Y}}(\tau)}\bigg\| \nabla\log\frac{\tilde p_{\tau | \tau_k}(\tilde{\mathbf{Y}}(\tau)| \tilde{\mathbf{z}}) }{\tilde p^\theta_{\tau | \tau_k}(\tilde{\mathbf{Y}}(\tau) | \tilde{\mathbf{z}}) }\bigg\|^2, 
    \end{align}
    for any fixed constant $C_{\text{KL}} > 0$, where the expectation is taken w.r.t. the conditional density $\tilde{\mathbf{Y}}(\tau)\sim \tilde p_{\tau | \tau_k}(\cdot | \tilde{\mathbf{z}})$ of the reverse SDE  (25) .
\end{enumerate}

For the terminal marginal density $q_{T_g}(\cdot | \mathbf{c})$ induced by the forward process defined in (3), if the moment condition (14) is satisfied, then we have:
    \begin{align*}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\text{KL}\big(q_{T_g}(\cdot | \mathbf{c}) || \mathcal{N}(0, I_d)\big)\bigg]\lesssim e^{-\frac{a}{2}T_g^2 - bT_g}\big[M_2 + de^{-\frac{a}{2}T_g^2 - bT_g}\big].
    \end{align*}

For the forward process $\mathbf{Y}$ in (3), if the moment condition (14) is satisfied, then we have:
    \begin{align*}
    &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\sum_{k=1}^{K} \int_{\tau_{k -1}}^{\tau_k}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[||f(\tau)\mathbf{Y}(\tau) - f(\tau_k)\mathbf{Y}(\tau_k)||^2\big]\mathrm{d}\tau\bigg] \\
    &\lesssim \Delta\tau(M_2 + d)(T_g + 1)^5.
\end{align*}

Suppose the first condition of Proposition~2 holds. Then for the forward process $\{\mathbf{Y}(\tau): \tau\in[0, T_g]\}$ in (3) and the corresponding score function $\{\nabla\log q_\tau(\cdot | \mathbf{c}): \tau\in[0, T_g]\}$, we have
    \begin{align*}
        &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\sum_{k=1}^{K}\int_{\tau_{k - 1}}^{\tau_{k}} \mathbb{E}_{\mathbf{Y}(\tau)\sim q_{\tau}(\cdot | \mathbf{c}),\mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}[\big\| g^2(\tau)\nabla\log q_{\tau}(\mathbf{Y}(\tau)|\mathbf{c}) -  g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k)| \mathbf{c}) \big\|]^2\mathrm{d} \tau\bigg]\\
        &\lesssim M_2\Delta\tau (T_g + 1)^2 + d\Delta\tau \big[L_1 + (T_g + 1)^4 \big].
    \end{align*}

Under the same condition as in Lemma~4, we have
    \begin{align*}
        &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\sum_{k=1}^{K}\int_{\tau_{k - 1}}^{\tau_{k}}[g^2(\tau_k) - g^2(\tau)]^2\mathbb{E}_{\mathbf{Y}(\tau)\sim q_{\tau}(\cdot | \mathbf{c})} \big[\big\|\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c})\big\|^2\big] \mathrm{d}\tau\bigg]\\
        & \quad \lesssim d(\Delta\tau)^2[L_1 + T_g + 1].
    \end{align*}

Given a condition $\mathbf{c}$, for any $1\le k_0 \le k_1$ and any $s\in(\tau_{k_0 - 1}, \tau_{k_0}]$, we have
    \begin{align*}
    &\int_{s}^{\tau_{k_0}}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_{k_0})\sim q_{\tau_{k_0} | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|g^2(\tau)\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_{k_0})\nabla\log q_{\tau_{k_0}}(\mathbf{Y}(\tau_{k_0}) | \mathbf{c} ) \|^2\big] \mathrm{d}\tau\\
    &\quad +\sum_{k=k_0 + 1}^{K}\int_{\tau_{k - 1}}^{\tau_k}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|g^2(\tau)\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c} ) \|^2\big] \mathrm{d}\tau\\
    &\lesssim \Delta\tau(T_g + 1)^2\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}\big[\|\mathbf{Y}(0)\|^2\big] + d\Delta\tau\bigg[\ln\bigg(\frac{1}{s} \bigg) + \frac{1}{s} + (T_g + 1)^4 \bigg].
    \end{align*}

Assume $\nabla\log p_{\text{target}}(\cdot|\mathbf{c})$ is $L(\mathbf{c})$-Lipschitz continuous for a given condition $\mathbf{c}$. If for some $1\le k \le k_1$, there exists $s \in [\tau_{k - 1}, \tau_k]$ satisfying $\sigma_{s}^2\le \frac{\lambda_{s}}{2L(\mathbf{c})}$, then
    \begin{align*}
        & \int_{\tau_{k - 1}}^{s}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|g^2(\tau)\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c}) - g^2(\tau_k)\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c})\|^2\big]\mathrm{d} \tau\\
        &\lesssim d(\Delta\tau)^2L(\mathbf{c})(L(\mathbf{c}) + 1)(\tau_k + 1)^6.
    \end{align*}

Suppose the following conditions hold:
\begin{enumerate}
    \item for any given condition $\mathbf{c}$, the target conditional distribution admits a twice continuously differentiable density function $p_{\text{target}}(\cdot | \mathbf{c})$, which is positive almost everywhere on $\mathbb{R}^{d_{\text{target}}}$ and the corresponding score function $\nabla\log p_{\text{target}}(\cdot | \mathbf{c})$ is $L(\mathbf{c})$-Lipschitz continuous with
    \begin{align}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}[L(\mathbf{c})] = L_1 < \infty.
    \end{align}

    \item The target distribution has a finite second moment, i.e.
    \begin{align}
        \mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\big[\mathbb{E}_{\mathbf{Y}(0)\sim p_{\text{target}}(\cdot | \mathbf{c})}||\mathbf{Y}(0)||^2\big] < M_2
    \end{align}
    for some positive constant $M_2$.

    \item There exists a small constant $\varepsilon_{\text{score}}>0$ such that
    \begin{align}
        \frac{1}{K}\sum_{k=1}^K\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\bigg[\mathbb{E}_{\mathbf{Y}(\tau_k)\sim q_{\tau_k}(\cdot | \mathbf{c})}\big[||\nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c}) - s_\theta(\tau_k, \mathbf{Y}(\tau_k), \mathbf{c})||^2\big]\bigg] \le \varepsilon_{\text{score}}^2.
    \end{align}
\end{enumerate}

Then, we have
\begin{align}
    &\mathbb{E}_{\mathbf{c}\sim\mathbf{C}}\left[\text{KL}\big(p_{\text{target}}(\cdot | \mathbf{c}) || \tilde p^\theta_{\tau_K}(\cdot | \mathbf{c})\big)\right]\\
    &\lesssim \underbrace{e^{-\frac{a}{2}T_g^2 - bT_g}\big[M_2 + de^{-\frac{a}{2}T_g^2 - bT_g}\big]}_{{\text(i)}} + \underbrace{(T_g + 1)^3 \varepsilon_{\text{score}}^2}_{\text{(ii)}} + \underbrace{\Delta\tau(M_2 + d)(T_g + 1)^5}_{\text{(iii)}} \\
    &\qquad + \underbrace{M_2\Delta\tau (T_g + 1)^2 + d\Delta\tau \big[L_1 + (T_g + 1)^4 \big]}_{\text{(iv)}} + \underbrace{d(\Delta\tau)^2(L_1 + T_g + 1)}_{\text{(v)}}. 
\end{align}

Under condition $\mathbf{c}$, if we define the process $\mathbf{Y}$ and $\mathbf{U}$ according to (3) and (57), respectively, and consider a time change
    \begin{equation}
        \tau(s) = \inf\big\{u: \exp(au^2/2 + bu) - 1 > s^{-1}\big\},
    \end{equation}
    then $\{\mathbf{U}(s): s\ge 0\}$ and $\{ s\lambda_{\tau(s)}^{-1}\mathbf{Y}(\tau(s)): s\ge 0\}$ have the same law, where $\lambda_\tau$ is defined in (22).

For any given condition $\mathbf{c}$ and any $\tau \in (0, T_g]$, we have
    \begin{align*}
        \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}\big[\|\nabla^2\log q_\tau(\mathbf{Y}_\tau|\mathbf{c})\|_F^2\big]\le d\sigma_\tau^{-4} + \frac{1}{g^2(\tau)}\cdot \frac{\mathrm{d}}{\mathrm{d}\tau}\bigg(\sigma_\tau^{-4}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_\tau(\mathbf{Y}(\tau), \mathbf{c}))]\bigg).
    \end{align*}

For any given condition $\mathbf{c}$ and $\tau \in (0, T_g]$, let $q_{0|\tau}(\cdot | \mathbf{y}(\tau), \mathbf{c})$ be the conditional distribution of $\mathbf{Y}(0)$ given $\mathbf{c}$ and $\mathbf{Y}(\tau)=\mathbf{y}(\tau)$, and $\boldsymbol{\Sigma}_\tau(\mathbf{y}(\tau), \mathbf{c}) = {\text{Cov}}_{\mathbf{Y}(0)\sim q_{0|\tau}(\cdot | \mathbf{y}(\tau), \mathbf{c})}\big(\mathbf{Y}(0)\big)$ be the corresponding conditional covariance matrix. Then for any $\tau > 0$, when $\tau\in[\tau_{k - 1}, \tau_k]$, we have
    \begin{align*}
    &\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c}), \mathbf{Y}(\tau_k)\sim q_{\tau_k | \tau}(\cdot | \mathbf{Y}(\tau), \mathbf{c})}\big[\|\nabla\log q_{\tau}(\mathbf{Y}(\tau) | \mathbf{c}) - \nabla\log q_{\tau_k}(\mathbf{Y}(\tau_k) | \mathbf{c} ) \|^2\big]\\
    &\le \int_{\tau}^{\tau_k} f(s)d\sigma^{-2}_{\tau_k} + g^2(s)d\sigma^{-4}_{s} \mathrm{d} s\\
    &\qquad + \sigma_{\tau_k}^{-4}\mathbb{E}_{\mathbf{Y}(\tau_k)\sim q_{\tau_k}(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_{\tau_k}(\mathbf{Y}(\tau_k), \mathbf{c}))] - \sigma_{\tau}^{-4}\mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}[\text{trace}(\boldsymbol{\Sigma}_{\tau}(\mathbf{Y}(\tau), \mathbf{c}))].
\end{align*}

For any given condition $\mathbf{c}$ and $\tau \in (0, T_g]$, and the marginal density $q_\tau(\cdot | \mathbf{c})$ defined by the forward process (3), we have
    \begin{align*}
        \mathbb{E}_{\mathbf{Y}(\tau)\sim q_\tau(\cdot | \mathbf{c})}\|\nabla\log q_\tau(\mathbf{Y}(\tau) | \mathbf{c})\|^2 \le \frac{d}{\sigma_\tau^2},
    \end{align*}
    where $\sigma_\tau^2$ is the conditional variance defined in (22).
